  "pitch.claimsBadge": "FDA, FSSAI या Organic दावे कभी न गढ़ें",
  "pitch.claimsBody": "खरीदार और कस्टम अधिकारी सख़्त अनुपालन जाँच करते हैं। केवल वही कहें जिसके लिए आपके पास दस्तावेज़ हैं। नीचे हर बिंदु जाँचें:",
  "pitch.check": "जाँच {n}:",
  "pitch.claimDefault1": "उत्पाद की सामग्री संरचना और प्रयोगशाला जाँच रिपोर्ट सत्यापित करें",
  "pitch.claimDefault2": "FDA, FSSAI या ऑर्गेनिक प्रमाणपत्र सत्यापित करें (वैध प्रमाणपत्र के बिना कभी दावा न करें)",
  "pitch.claimDefault3": "उत्पादन क्षमता और डिलीवरी समय-सारणी की पुष्टि करें",
  "pitch.claimDefault4": "सुनिश्चित करें कि लकड़ी के पैलेट पर ISPM-15 हीट-ट्रीटेड मुहर हो",
  "pitch.scamTitle": "धोखाधड़ी चेतावनी: नकली खरीदार और अग्रिम भुगतान धोखा",
  "pitch.scamFeeTitle": "• नकली निरीक्षण और पंजीकरण शुल्क:",
  "pitch.scamFeeBody": "खरीदार बनकर धोखेबाज़ आपसे किसी असत्यापित एजेंसी को अग्रिम \"विक्रेता पंजीकरण शुल्क\" या \"लैब निरीक्षण शुल्क\" भेजने को कहते हैं। असली खरीदार अपनी निरीक्षण एजेंसियों (SGS, Intertek) को स्वयं भुगतान करते हैं।",
  "pitch.scamCheckTitle": "• चेक और अधिक भुगतान वायर धोखा:",
  "pitch.scamCheckBody": "अधिक राशि वाला चेक लेकर बाकी रकम वापस भेजने की माँग कभी स्वीकार न करें। व्यावसायिक बैंकों के ज़रिए सत्यापित अपरिवर्तनीय साख-पत्र (L/C) या एस्क्रो पर ज़ोर दें।",
  "pitch.adviceIn": "{native} ({name}) में निर्यातक सलाह:",
  "pitch.important": "महत्वपूर्ण सूचना:",
  "pitch.importantBody": "बिक्री के नतीजों का कभी वादा न करें। शिपिंग करते समय HTS शुल्क कोड, आयात शुल्क और प्रवेश मंज़ूरी के अंतिम निर्णय के लिए लाइसेंसधारी कस्टम ब्रोकर से जाँच करें।",
  "trans.clearSession": "सत्र साफ़ करें",
  "trans.clearTitle": "इस सत्र के अनुवाद मिटाएँ",
  "trans.badge": "व्यापार अनुवाद",
