  "trans.subtitle": "Zoom कॉल या फ़ोन पर बातचीत के दौरान इस्तेमाल करें। थोथ बिना वादे जोड़े या मोलभाव किए सटीक अनुवाद करता है। दोहराव से हर कीमत और Incoterm की पुष्टि होती है।",
  "trans.ruleTitle": "नियम:",
  "trans.ruleBody": "शुल्क केवल संभावित हैं, जाँचें। अंतिम निर्णय के लिए हमेशा लाइसेंसधारी कस्टम ब्रोकर से जाँच करें।",
