  "pitch.scamFeeBody": "खरेदीदार असल्याचे भासवणारे फसवणूक करणारे तुम्हाला एखाद्या असत्यापित संस्थेला आगाऊ \"विक्रेता नोंदणी शुल्क\" किंवा \"लॅब तपासणी शुल्क\" पाठवायला सांगतात. खरे खरेदीदार आपल्या तपासणी संस्थांना (SGS, Intertek) स्वतः पैसे देतात.",
