  "guide.badgeSub": "नवीन आणि अनुभवी निर्यातदारांसाठी सोपे शब्द",
  "guide.title": "कस्टम, शिपिंग अटी आणि अनुपालन सोप्या भाषेत समजून घ्या",
  "guide.subtitle": "खरेदीदारांना शिपिंग अटी (FOB विरुद्ध CIF), योग्य लेबलिंग आणि प्रमाणित कागदपत्रांबद्दल स्पष्टता हवी असते. किंमत सांगण्यापूर्वी मूलभूत गोष्टी शिका!",
