  "guide.askBtn": "थोथला विचारा",
  "guide.explaining": "समजावत आहे...",
  "guide.answerTitle": "थोथचे सोप्या भाषेतील स्पष्टीकरण:",
  "guide.listen": "ऐका",
  "guide.stopVoice": "आवाज थांबवा",
  "guide.sampleQ1": "खरेदीदारांसाठी FOB आणि CIF मध्ये काय फरक आहे?",
  "guide.sampleQ2": "निर्यात केलेल्या उत्पादनांवर कोणते लेबलिंग बंधनकारक आहे?",
  "guide.sampleQ3": "माझ्या उत्पादनाचा योग्य HS कोड कसा शोधू?",
  "guide.sampleQ4": "कस्टम शुल्क खरेदीदार भरतो की निर्यातदार?",
  "guide.sampleQ5": "माझे लाकडी पॅलेट ISPM-15 प्रमाणित नसतील तर काय होईल?",
  "guide.card1Tag": "संभाव्य कोड • तपासा",
  "guide.card1Title": "1. HS / HTS कोड आणि शुल्क दर",
  "guide.card1Body": "HS कोड (6 अंकी, आंतरराष्ट्रीय) आणि HTS कोड (10 अंकी) व त्यांच्याशी संबंधित शुल्क टक्केवारी फक्त तपासणीसाठी संभाव्य आहेत — शुल्क कधीही तथ्य म्हणून सांगू नका.",
  "guide.card1Note1": "• शुल्क दर बदलत असतात आणि सामग्रीच्या अचूक तपशील व मूळावर अवलंबून असतात.",
  "guide.card1Note2": "• कायदेशीर वर्गीकरण फक्त गंतव्य देशाचे कस्टम प्राधिकरण आणि परवानाधारक कस्टम ब्रोकर ठरवतात.",
  "guide.card2Title": "2. शिपिंग अटी: FOB विरुद्ध CIF",
  "guide.card2Body": "FOB (Incoterm): देशांतर्गत वाहतूक आणि तुमच्या मूळ बंदरावर जहाजात माल चढवण्याचा खर्च तुम्ही करता. समुद्री भाडे आणि कस्टम खरेदीदार भरतो.",
  "guide.card2Note1": "• बहुतेक निर्यातदारांसाठी FOB सर्वोत्तम आहे.",
  "guide.card2Note2": "• CIF म्हणजे गंतव्य बंदरापर्यंतचे समुद्री भाडे आणि विमा तुम्ही भरता.",
  "guide.card3Title": "3. अनिवार्य मूळ लेबल",
  "guide.card3Body": "आयात नियमांनुसार साधारणपणे वस्तूंवर त्यांचा मूळ देश इंग्रजीत, स्पष्ट दिसेल आणि न पुसला जाईल अशा प्रकारे लिहिणे आवश्यक असते — अचूक नियम परवानाधारक कस्टम ब्रोकरकडून निश्चित करा.",
  "guide.card3Note1": "• प्रत्येक उत्पादन आणि मुख्य शिपिंग खोके दोन्हीवर खूण करा.",
  "guide.card3Note2": "• स्पष्ट वाचता आले पाहिजे: मूळ देश, इंग्रजीत.",
  "guide.card4Title": "4. पॅलेट आणि ISPM-15 प्रक्रिया",
  "guide.card4Body": "सर्व भरीव लाकडी पॅकेजिंग (पॅलेट, क्रेट, डनेज) उष्णता-प्रक्रिया केलेले असावे आणि त्यावर अधिकृत ISPM-15 गव्हाच्या लोंबीचा शिक्का असावा.",
  "guide.card4Note1": "• नियम न पाळणारे लाकूड गंतव्य बंदरावरून निर्यातदाराच्या खर्चाने परत पाठवले जाते.",
  "guide.card4Note2": "• पर्याय म्हणून प्लास्टिक किंवा दाबलेल्या कागदाचे पॅलेट वापरा.",
  "guide.card5Title": "5. आवश्यक निर्यात कागदपत्रे",
  "guide.card5Body": "प्रत्येक शिपमेंटसाठी चार स्वच्छ, अचूक कागदपत्रे लागतात:",
  "guide.card5Doc1": "1. व्यावसायिक बीजक (USD मध्ये वस्तूनिहाय मूल्य)",
  "guide.card5Doc2": "2. पॅकिंग यादी (एकूण/निव्वळ वजन, खोक्यांची संख्या)",
  "guide.card5Doc3": "3. बिल ऑफ लेडिंग (शिपिंग लाइनकडून B/L)",
  "guide.card5Doc4": "4. मूळ प्रमाणपत्र (मूळ देशात जारी)",
  "guide.card6Title": "6. कस्टम ब्रोकरची भूमिका",
  "guide.card6Body": "परवानाधारक कस्टम ब्रोकर आयात नोंदी (साधारणपणे फॉर्म 7501) दाखल करण्यास आणि बॉन्ड हाताळण्यास अधिकृत असतो — सध्याचा फॉर्म आणि आवश्यकता तुमच्या ब्रोकरकडून निश्चित करा.",
  "guide.card6Golden": "सुवर्ण नियम:",
  "guide.card6GoldenBody": "थोथ तुम्हाला माहिती आणि पिचची साधने देतो; कंटेनर बुक करण्यापूर्वी अंतिम निर्णयासाठी परवानाधारक कस्टम ब्रोकरकडून खात्री करा.",
  "guide.card7Title": "7. सुरक्षा मार्गदर्शक: बनावट खरेदीदार आणि आगाऊ पैसे फसवणुकीपासून सावध रहा",
  "guide.card7Sub1Title": "1. आगाऊ \"तपासणी शुल्क\" फसवणूक:",
