  "safety.item1Body": "થોથ એક પહેલ છે, જે ઉત્પાદકો, MSME, કારીગરો અને નિકાસકારોની મદદ માટે છે. અમે ક્યારેય ક્રેડિટ કાર્ડ કે બેંક વિગતો માંગતા નથી.",
