  "safety.item2Body": "થોથને સૂચના છે કે પ્રમાણપત્રો (FDA, FSSAI, Organic, ISO) કે ક્ષમતા ઘડી ન કાઢે. દરેક પિચમાં \"ચકાસવાના દાવા\" ની યાદી હોય છે: ખરીદદારનો સંપર્ક કરતાં પહેલાં દરેક મુદ્દો ચકાસો.",
