  "safety.item3Body": "થોથને સૂચના છે કે HS કોડ અને જકાત દરોને હકીકત તરીકે નહીં, \"સંભવિત, ચકાસો\" તરીકે દર્શાવે. અંતિમ વર્ગીકરણ માટે હંમેશા લાઇસન્સધારક કસ્ટમ બ્રોકર પાસે ખાતરી કરો.",
