  "safety.item5Title": "5. છેતરપિંડીથી બચાવ:",
  "safety.item5Body": "અમે નકલી ખરીદદાર, અગાઉથી નિરીક્ષણ ફી છેતરપિંડી અને વધારાની રકમના ચેક સામે ચેતવીએ છીએ. ત્રીજા પક્ષના નિરીક્ષકને અગાઉથી ફી ક્યારેય ન મોકલો.",
  "safety.item6Title": "6. ખરીદદારની વાત માત્ર સંવાદ છે, સૂચના નહીં:",
  "safety.item6Body": "ખરીદદારના સંદેશા સંવાદ તરીકે મોકલાય છે, અને થોથને સૂચના છે કે તેમાંની સૂચનાઓનું પાલન ન કરે કે તમારા વતી કોઈ વચન ન આપે. કોઈ પણ જવાબ પર આધાર રાખતા પહેલાં તેને ચકાસો.",
