  "safety.item7Body": "તમે મોકલેલું લખાણ જવાબ બનાવવા માટે Google ના Gemini API ને મોકલવામાં આવે છે; Google તેને કેવી રીતે સંભાળે છે તે આ ઍપના નિયંત્રણમાં નથી. વૉઇસ ઇનપુટ તમારા બ્રાઉઝરની વાણી ઓળખનો ઉપયોગ કરે છે. Gemini કી સર્વર પર જ રહે છે અને પેજમાં સામેલ નથી.",
