  "pitch.scamFeeBody": "ખરીદદાર હોવાનો ઢોંગ કરનારા છેતરપિંડી કરનારાઓ તમને કોઈ અચકાસાયેલ એજન્સીને અગાઉથી \"વેન્ડર નોંધણી ફી\" કે \"લૅબ નિરીક્ષણ ચાર્જ\" મોકલવા કહે છે. સાચા ખરીદદારો પોતાની નિરીક્ષણ એજન્સીઓને (SGS, Intertek) જાતે ચૂકવે છે.",
  "pitch.scamCheckTitle": "• ચેક અને વધારાની ચુકવણી વાયર છેતરપિંડી:",
  "pitch.scamCheckBody": "વધારાની રકમનો ચેક લઈને બાકીની રકમ પાછી મોકલવાની માંગ ક્યારેય સ્વીકારશો નહીં. વ્યાપારી બેંકો મારફતે ચકાસાયેલ અફર શાખપત્ર (L/C) કે એસ્ક્રોનો આગ્રહ રાખો.",
