  "trans.readbackTitle": "વેપાર શરતોનું પુનઃવાંચન (સચોટ, વાટાઘાટ વગર):",
  "trans.confirmBtn": "પુનઃવાંચનની ખાતરી માટે ક્લિક કરો",
