  "safety.item1Title": "1. সবার জন্য উন্মুক্ত:",
  "safety.item1Body": "থথ একটি উদ্যোগ, যা নির্মাতা, MSME, কারিগর ও রপ্তানিকারকদের সাহায্যের জন্য। আমরা কখনো ক্রেডিট কার্ড বা ব্যাংকের তথ্য চাই না।",
  "safety.item2Title": "2. বানানো দাবি বা সনদ নয়:",
  "safety.item2Body": "থথকে নির্দেশ দেওয়া আছে সনদ (FDA, FSSAI, Organic, ISO) বা উৎপাদন ক্ষমতা বানিয়ে না বলতে। প্রতিটি পিচে \"যাচাই করার দাবি\" তালিকা থাকে: ক্রেতার সাথে যোগাযোগের আগে প্রতিটি বিষয় যাচাই করুন।",
  "safety.item3Title": "3. HS কোড ও শুল্ক শুধু সম্ভাব্য:",
  "safety.item3Body": "থথকে নির্দেশ দেওয়া আছে HS কোড ও শুল্কের হারকে তথ্য হিসেবে নয়, \"সম্ভাব্য, যাচাই করুন\" হিসেবে দেখাতে। চূড়ান্ত শ্রেণিবিন্যাসের জন্য সবসময় লাইসেন্সপ্রাপ্ত কাস্টমস ব্রোকারের সাথে যাচাই করুন।",
  "safety.item4Title": "4. বিশ্বস্ত অনুবাদ ও শর্তের পুনঃপাঠ:",
  "safety.item4Body": "থথকে নির্দেশ দেওয়া আছে অনুবাদে কোনো প্রতিশ্রুতি যোগ না করতে বা দরকষাকষি না করতে, এবং দাম, মুদ্রা (USD/INR), একক ও Incoterm আপনার নিশ্চিতকরণের জন্য আবার পড়ে শোনাতে।",
  "safety.item5Title": "5. প্রতারণা থেকে সুরক্ষা:",
  "safety.item5Body": "আমরা ভুয়া ক্রেতা, অগ্রিম পরিদর্শন ফি প্রতারণা ও অতিরিক্ত টাকার চেক সম্পর্কে সতর্ক করি। তৃতীয় পক্ষের পরিদর্শককে কখনো অগ্রিম ফি পাঠাবেন না।",
  "safety.item6Title": "6. ক্রেতার কথা শুধু কথোপকথন, নির্দেশ নয়:",
  "safety.item6Body": "ক্রেতার বার্তা কথোপকথন হিসেবে পাঠানো হয়, এবং থথকে নির্দেশ দেওয়া আছে সেগুলোর ভেতরের নির্দেশ না মানতে বা আপনার হয়ে কোনো প্রতিশ্রুতি না দিতে। কোনো উত্তরের ওপর নির্ভর করার আগে তা যাচাই করুন।",
  "safety.item7Title": "7. আপনার লেখা কোথায় যায়:",
  "safety.item7Body": "আপনি যে লেখা পাঠান তা উত্তর তৈরির জন্য Google-এর Gemini API-তে পাঠানো হয়; Google তা কীভাবে ব্যবহার করে তা এই অ্যাপের নিয়ন্ত্রণে নেই। ভয়েস ইনপুট আপনার ব্রাউজারের কণ্ঠ শনাক্তকরণ ব্যবহার করে। Gemini কী সার্ভারেই থাকে এবং পেজে অন্তর্ভুক্ত নয়।",
