  "guide.sampleQ2": "রপ্তানি পণ্যে কোন লেবেলিং বাধ্যতামূলক?",
  "guide.sampleQ3": "আমার পণ্যের সঠিক HS কোড কীভাবে খুঁজব?",
  "guide.sampleQ4": "কাস্টমস শুল্ক ক্রেতা দেন নাকি রপ্তানিকারক?",
  "guide.sampleQ5": "আমার কাঠের প্যালেট ISPM-15 সনদপ্রাপ্ত না হলে কী হবে?",
  "guide.card1Tag": "সম্ভাব্য কোড • যাচাই করুন",
  "guide.card1Title": "1. HS / HTS কোড ও শুল্কের হার",
  "guide.card1Body": "HS কোড (6 অঙ্ক, আন্তর্জাতিক) ও HTS কোড (10 অঙ্ক) এবং সংশ্লিষ্ট শুল্কের শতাংশ শুধু যাচাইয়ের জন্য সম্ভাব্য — শুল্ককে কখনো তথ্য হিসেবে বলবেন না।",
  "guide.card1Note1": "• শুল্কের হার বদলায় এবং উপাদানের সঠিক বিবরণ ও উৎসের ওপর নির্ভর করে।",
  "guide.card1Note2": "• আইনি শ্রেণিবিন্যাস কেবল গন্তব্য দেশের কাস্টমস কর্তৃপক্ষ ও লাইসেন্সপ্রাপ্ত কাস্টমস ব্রোকার ঠিক করেন।",
  "guide.card2Title": "2. শিপিং শর্ত: FOB বনাম CIF",
  "guide.card2Body": "FOB (Incoterm): দেশের ভেতরের পরিবহন ও আপনার উৎস বন্দরে জাহাজে মাল তোলার খরচ আপনি দেন। সমুদ্র ভাড়া ও কাস্টমস ক্রেতা দেন।",
  "guide.card2Note1": "• বেশিরভাগ রপ্তানিকারকের জন্য FOB সবচেয়ে ভালো।",
  "guide.card2Note2": "• CIF মানে গন্তব্য বন্দর পর্যন্ত সমুদ্র ভাড়া ও বিমা আপনি দেন।",
  "guide.card3Title": "3. বাধ্যতামূলক উৎস লেবেল",
  "guide.card3Body": "আমদানি বিধি সাধারণত চায় যে পণ্যে তার উৎস দেশ ইংরেজিতে, স্পষ্টভাবে ও অমোচনীয়ভাবে লেখা থাকবে — সঠিক নিয়ম লাইসেন্সপ্রাপ্ত কাস্টমস ব্রোকারের কাছে নিশ্চিত করুন।",
  "guide.card3Note1": "• প্রতিটি পণ্য এবং মূল শিপিং কার্টন দুটোতেই চিহ্ন দিন।",
  "guide.card3Note2": "• স্পষ্ট পড়া যেতে হবে: উৎস দেশ, ইংরেজিতে।",
  "guide.card4Title": "4. প্যালেট ও ISPM-15 শোধন",
  "guide.card4Body": "সব নিরেট কাঠের প্যাকেজিং (প্যালেট, ক্রেট, ডানেজ) তাপ-শোধিত হতে হবে এবং তাতে সরকারি ISPM-15 গমের শিষের ছাপ থাকতে হবে।",
  "guide.card4Note1": "• নিয়ম না মানা কাঠ গন্তব্য বন্দর থেকে রপ্তানিকারকের খরচে ফেরত পাঠানো হয়।",
  "guide.card4Note2": "• বিকল্প হিসেবে প্লাস্টিক বা চাপা কাগজের প্যালেট ব্যবহার করুন।",
  "guide.card5Title": "5. প্রয়োজনীয় রপ্তানি নথি",
  "guide.card5Body": "প্রতিটি চালানে চারটি পরিচ্ছন্ন, সঠিক কাগজ লাগে:",
  "guide.card5Doc1": "1. বাণিজ্যিক চালান (USD-এ পণ্যভিত্তিক মূল্য)",
  "guide.card5Doc2": "2. প্যাকিং তালিকা (মোট/নিট ওজন, কার্টনের সংখ্যা)",
  "guide.card5Doc3": "3. বিল অব লেডিং (শিপিং লাইন থেকে B/L)",
  "guide.card5Doc4": "4. উৎস সনদ (উৎস দেশে ইস্যু করা)",
  "guide.card6Title": "6. কাস্টমস ব্রোকারের ভূমিকা",
  "guide.card6Body": "লাইসেন্সপ্রাপ্ত কাস্টমস ব্রোকার আমদানি এন্ট্রি (সাধারণত ফর্ম 7501) দাখিল ও বন্ড সামলানোর জন্য অনুমোদিত — বর্তমান ফর্ম ও শর্ত আপনার ব্রোকারের কাছে নিশ্চিত করুন।",
  "guide.card6Golden": "সোনালি নিয়ম:",
  "guide.card6GoldenBody": "থথ আপনাকে শিক্ষা ও পিচের সরঞ্জাম দেয়; কন্টেইনার বুক করার আগে চূড়ান্ত সিদ্ধান্তের জন্য লাইসেন্সপ্রাপ্ত কাস্টমস ব্রোকারের সাথে যাচাই করুন।",
  "guide.card7Title": "7. সুরক্ষা নির্দেশিকা: ভুয়া ক্রেতা ও অগ্রিম অর্থ প্রতারণা থেকে সাবধান",
  "guide.card7Sub1Title": "1. অগ্রিম \"পরিদর্শন ফি\" প্রতারণা:",
  "guide.card7Sub1Body": "প্রতারক একটি বড় ক্রয় আদেশ পাঠায়, কিন্তু জোর দেয় যে আপনাকে কোনো অযাচাইকৃত তৃতীয় পক্ষকে অগ্রিম পরিদর্শন, বিক্রেতা তালিকাভুক্তি বা ল্যাব ফি দিতে হবে। প্রকৃত ক্রেতারা সনদপ্রাপ্ত সংস্থাকে (SGS, Intertek) নিজেরাই টাকা দেন।",
  "guide.card7Sub2Title": "2. অতিরিক্ত অর্থ ও চেক প্রতারণা:",
  "guide.card7Sub2Body": "প্রতারক চালানের চেয়ে বেশি টাকার জাল ব্যাংক চেক পাঠায়, তারপর \"অতিরিক্ত টাকা\" ফেরত পাঠাতে বলে। সরকারি ব্যাংক ওয়্যার পুরোপুরি জমা না হওয়া পর্যন্ত পণ্য বা টাকা পাঠাবেন না।",
  "guide.card7Sub3Title": "3. ক্রেতার ব্যবসার বৈধতা যাচাই করুন:",
  "guide.card7Sub3Body": "সরকারি ব্যবসা নিবন্ধন তালিকায় ক্রেতাকে খুঁজুন। কোম্পানির ইমেইল ডোমেইন সরকারি ওয়েবসাইটের সাথে মেলে কিনা, পাবলিক ওয়েবমেইল নয় তো, তা যাচাই করুন।",
