  "trans.readbackFallback": "மீண்டும் வாசிப்புச் சரிபார்ப்பு: ஒப்பந்தத்துக்கு முன் விலை, நாணயம், அளவு அலகுகள், Incoterm ஆகியவை சரிபார்க்கப்பட வேண்டும்.",
