  "pitch.subtitle": "కొనుగోలుదారులు సంక్షిప్తత, ఖచ్చితమైన పరిమాణాలు, నిజాయితీ వివరాలు మరియు స్పష్టమైన FOB నిబంధనలు కోరుకుంటారు. థోత్ సోర్సింగ్ ప్రమాణాలకు తగినట్లు స్పష్టమైన, అతిశయోక్తి లేని పిచ్‌లు రాస్తుంది.",
