  "pitch.claimsBadge": "FDA, FSSAI లేదా Organic వాదనలను ఎప్పుడూ కల్పించవద్దు",
  "pitch.claimsBody": "కొనుగోలుదారులు మరియు కస్టమ్స్ అధికారులు కఠినమైన అనుగుణ్యత తనిఖీలు చేస్తారు. మీ వద్ద పత్రాలు ఉన్నవాటినే చెప్పండి. కింది ప్రతి అంశాన్ని సరిచూసుకోండి:",
  "pitch.check": "తనిఖీ {n}:",
  "pitch.claimDefault1": "ఉత్పత్తి పదార్థ కూర్పు మరియు ప్రయోగశాల పరీక్ష నివేదికలను ధృవీకరించండి",
