  "pitch.scamTitle": "మోస హెచ్చరిక: నకిలీ కొనుగోలుదారులు మరియు ముందస్తు చెల్లింపు మోసం",
  "pitch.scamFeeTitle": "• నకిలీ తనిఖీ మరియు నమోదు రుసుము:",
  "pitch.scamFeeBody": "కొనుగోలుదారులుగా నటించే మోసగాళ్లు ధృవీకరించని సంస్థకు ముందుగానే \"విక్రేత నమోదు రుసుము\" లేదా \"ల్యాబ్ తనిఖీ ఛార్జ్\" పంపమని అడుగుతారు. నిజమైన కొనుగోలుదారులు తమ తనిఖీ సంస్థలకు (SGS, Intertek) తామే చెల్లిస్తారు.",
  "pitch.scamCheckTitle": "• చెక్ మరియు అధిక చెల్లింపు వైర్ మోసం:",
  "pitch.scamCheckBody": "అధిక మొత్తం చెక్కును తీసుకుని మిగులును తిరిగి పంపమనే అభ్యర్థనను ఎప్పుడూ అంగీకరించవద్దు. వాణిజ్య బ్యాంకుల ద్వారా ధృవీకరించిన మార్చలేని లెటర్ ఆఫ్ క్రెడిట్ (L/C) లేదా ఎస్క్రోను కోరండి.",
  "pitch.adviceIn": "{native} ({name})లో ఎగుమతిదారు సలహా:",
  "pitch.important": "ముఖ్య గమనిక:",
  "pitch.importantBody": "అమ్మకాల ఫలితాలకు ఎప్పుడూ హామీ ఇవ్వవద్దు. రవాణా చేసేటప్పుడు HTS సుంకం కోడ్‌లు, దిగుమతి సుంకాలు మరియు ప్రవేశ అనుమతి తుది నిర్ణయాల కోసం లైసెన్స్ ఉన్న కస్టమ్స్ బ్రోకర్‌తో సరిచూసుకోండి.",
