  "safety.item6Body": "ਖਰੀਦਦਾਰ ਦੇ ਸੁਨੇਹੇ ਗੱਲਬਾਤ ਵਜੋਂ ਭੇਜੇ ਜਾਂਦੇ ਹਨ, ਅਤੇ ਥੋਥ ਨੂੰ ਹਦਾਇਤ ਹੈ ਕਿ ਉਨ੍ਹਾਂ ਵਿਚਲੀਆਂ ਹਦਾਇਤਾਂ ਨਾ ਮੰਨੇ ਜਾਂ ਤੁਹਾਡੇ ਵੱਲੋਂ ਕੋਈ ਵਾਅਦਾ ਨਾ ਕਰੇ। ਕਿਸੇ ਵੀ ਜਵਾਬ ਉੱਤੇ ਭਰੋਸਾ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਉਸਨੂੰ ਜਾਂਚੋ।",
  "safety.item7Title": "7. ਤੁਹਾਡਾ ਲਿਖਿਆ ਕਿੱਥੇ ਜਾਂਦਾ ਹੈ:",
  "safety.item7Body": "ਤੁਸੀਂ ਜੋ ਲਿਖਤ ਭੇਜਦੇ ਹੋ, ਉਹ ਜਵਾਬ ਬਣਾਉਣ ਲਈ Google ਦੇ Gemini API ਨੂੰ ਭੇਜੀ ਜਾਂਦੀ ਹੈ; Google ਉਸਨੂੰ ਕਿਵੇਂ ਸੰਭਾਲਦਾ ਹੈ, ਇਹ ਇਸ ਐਪ ਦੇ ਕੰਟਰੋਲ ਵਿੱਚ ਨਹੀਂ। ਆਵਾਜ਼ ਇਨਪੁੱਟ ਤੁਹਾਡੇ ਬ੍ਰਾਊਜ਼ਰ ਦੀ ਬੋਲੀ ਪਛਾਣ ਵਰਤਦਾ ਹੈ। Gemini ਕੁੰਜੀ ਸਰਵਰ ਉੱਤੇ ਰਹਿੰਦੀ ਹੈ ਅਤੇ ਪੰਨੇ ਵਿੱਚ ਸ਼ਾਮਲ ਨਹੀਂ ਹੁੰਦੀ।",
  "safety.madeWith": "ਬਣਾਇਆ",
  "safety.byElghaly": "ਨਿਰਯਾਤਕਾਂ ਲਈ",
  "safety.close": "ਸਮਝ ਗਿਆ, ਬੰਦ ਕਰੋ",
