  "pitch.specPort": "ਮੂਲ ਬੰਦਰਗਾਹ",
  "pitch.claimsTitle": "ਖਰੀਦਦਾਰਾਂ ਨਾਲ ਸੰਪਰਕ ਤੋਂ ਪਹਿਲਾਂ ਜਾਂਚਣ ਵਾਲੇ ਦਾਅਵੇ",
  "pitch.claimsBadge": "FDA, FSSAI ਜਾਂ Organic ਦਾਅਵੇ ਕਦੇ ਨਾ ਘੜੋ",
  "pitch.claimsBody": "ਖਰੀਦਦਾਰ ਅਤੇ ਕਸਟਮ ਅਧਿਕਾਰੀ ਸਖ਼ਤ ਪਾਲਣਾ ਜਾਂਚ ਕਰਦੇ ਹਨ। ਸਿਰਫ਼ ਉਹੀ ਕਹੋ ਜਿਸਦੇ ਦਸਤਾਵੇਜ਼ ਤੁਹਾਡੇ ਕੋਲ ਹਨ। ਹੇਠਾਂ ਹਰ ਗੱਲ ਜਾਂਚੋ:",
  "pitch.check": "ਜਾਂਚ {n}:",
  "pitch.claimDefault1": "ਉਤਪਾਦ ਦੀ ਸਮੱਗਰੀ ਬਣਤਰ ਅਤੇ ਲੈਬ ਜਾਂਚ ਰਿਪੋਰਟਾਂ ਦੀ ਪੁਸ਼ਟੀ ਕਰੋ",
  "pitch.claimDefault2": "FDA, FSSAI ਜਾਂ ਜੈਵਿਕ ਸਰਟੀਫਿਕੇਟਾਂ ਦੀ ਪੁਸ਼ਟੀ ਕਰੋ (ਵੈਧ ਸਰਟੀਫਿਕੇਟ ਤੋਂ ਬਿਨਾਂ ਕਦੇ ਦਾਅਵਾ ਨਾ ਕਰੋ)",
  "pitch.claimDefault3": "ਉਤਪਾਦਨ ਸਮਰੱਥਾ ਅਤੇ ਡਿਲੀਵਰੀ ਸਮਾਂ-ਸਾਰਣੀ ਦੀ ਪੁਸ਼ਟੀ ਕਰੋ",
  "pitch.claimDefault4": "ਯਕੀਨੀ ਬਣਾਓ ਕਿ ਲੱਕੜ ਦੇ ਪੈਲੇਟਾਂ ਉੱਤੇ ISPM-15 ਗਰਮੀ-ਉਪਚਾਰ ਮੋਹਰ ਹੋਵੇ",
  "pitch.scamTitle": "ਧੋਖਾਧੜੀ ਚੇਤਾਵਨੀ: ਨਕਲੀ ਖਰੀਦਦਾਰ ਅਤੇ ਪੇਸ਼ਗੀ ਭੁਗਤਾਨ ਧੋਖਾ",
  "pitch.scamFeeTitle": "• ਨਕਲੀ ਨਿਰੀਖਣ ਅਤੇ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਫੀਸ:",
  "pitch.scamFeeBody": "ਖਰੀਦਦਾਰ ਬਣ ਕੇ ਧੋਖੇਬਾਜ਼ ਤੁਹਾਨੂੰ ਕਿਸੇ ਅਣ-ਪ੍ਰਮਾਣਿਤ ਏਜੰਸੀ ਨੂੰ ਪੇਸ਼ਗੀ \"ਵਿਕਰੇਤਾ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਫੀਸ\" ਜਾਂ \"ਲੈਬ ਨਿਰੀਖਣ ਖ਼ਰਚਾ\" ਭੇਜਣ ਲਈ ਕਹਿੰਦੇ ਹਨ। ਅਸਲੀ ਖਰੀਦਦਾਰ ਆਪਣੀਆਂ ਨਿਰੀਖਣ ਏਜੰਸੀਆਂ (SGS, Intertek) ਨੂੰ ਖ਼ੁਦ ਭੁਗਤਾਨ ਕਰਦੇ ਹਨ।",
  "pitch.scamCheckTitle": "• ਚੈੱਕ ਅਤੇ ਵੱਧ ਭੁਗਤਾਨ ਵਾਇਰ ਧੋਖਾ:",
  "pitch.scamCheckBody": "ਵੱਧ ਰਕਮ ਵਾਲਾ ਚੈੱਕ ਲੈ ਕੇ ਬਾਕੀ ਰਕਮ ਵਾਪਸ ਭੇਜਣ ਦੀ ਮੰਗ ਕਦੇ ਨਾ ਮੰਨੋ। ਵਪਾਰਕ ਬੈਂਕਾਂ ਰਾਹੀਂ ਪ੍ਰਮਾਣਿਤ ਅਟੱਲ ਲੈਟਰ ਆਫ਼ ਕ੍ਰੈਡਿਟ (L/C) ਜਾਂ ਐਸਕ੍ਰੋ ਉੱਤੇ ਜ਼ੋਰ ਦਿਓ।",
  "pitch.adviceIn": "{native} ({name}) ਵਿੱਚ ਨਿਰਯਾਤਕ ਸਲਾਹ:",
  "pitch.important": "ਮਹੱਤਵਪੂਰਨ ਸੂਚਨਾ:",
  "pitch.importantBody": "ਵਿਕਰੀ ਦੇ ਨਤੀਜਿਆਂ ਦਾ ਕਦੇ ਵਾਅਦਾ ਨਾ ਕਰੋ। ਮਾਲ ਭੇਜਦੇ ਸਮੇਂ HTS ਡਿਊਟੀ ਕੋਡ, ਆਯਾਤ ਡਿਊਟੀ ਅਤੇ ਦਾਖ਼ਲਾ ਮਨਜ਼ੂਰੀ ਦੇ ਅੰਤਿਮ ਫ਼ੈਸਲਿਆਂ ਲਈ ਲਾਇਸੈਂਸਸ਼ੁਦਾ ਕਸਟਮ ਬ੍ਰੋਕਰ ਤੋਂ ਜਾਂਚ ਕਰੋ।",
