  "safety.title": "ميثاق الثقة والأخلاقيات في Thoth",
  "safety.subtitle": "صُنع بعناية من أجل المصدّرين",
  "safety.item1Title": "1. مفتوح للجميع:",
  "safety.item1Body": "Thoth مبادرة لمساعدة المصنّعين والمشروعات الصغيرة والمتوسطة والحرفيين والمصدّرين. لا نطلب أبدًا بيانات بطاقة ائتمان أو حساب بنكي.",
  "safety.item2Title": "2. لا ادعاءات أو شهادات مختلَقة:",
  "safety.item2Body": "Thoth موجَّه بعدم اختلاق شهادات (FDA أو FSSAI أو Organic أو ISO) أو طاقات إنتاجية. كل عرض يتضمن قائمة «ادعاءات تحتاج تحققًا»: راجع كل بند قبل التواصل مع المشتري.",
  "safety.item3Title": "3. رموز HS والتعريفات مرشّحة فقط:",
  "safety.item3Body": "Thoth موجَّه بأن يوسم رموز HS ونسب الرسوم بأنها «مرشّحة، تحتاج تحققًا» لا حقائق. راجع دائمًا مخلّصًا جمركيًا مرخّصًا للتصنيف النهائي.",
  "safety.item4Title": "4. ترجمة أمينة وإعادة قراءة الشروط:",
  "safety.item4Body": "Thoth موجَّه بأن يترجم دون إضافة التزامات أو تفاوض، وأن يعيد قراءة السعر والعملة (USD/INR) والوحدات وIncoterm لتؤكدها.",
  "safety.item5Title": "5. الحماية من الاحتيال:",
  "safety.item5Body": "نحذّر من احتيال المشترين المزيفين ورسوم الفحص المقدَّمة وشيكات الدفع الزائد. لا تحوّل أبدًا رسومًا مقدمة لجهات فحص خارجية.",
  "safety.item6Title": "6. كلام المشتري بيانات وليس تعليمات:",
  "safety.item6Body": "تُرسل رسائل المشتري كمحتوى حوار، وThoth موجَّه بعدم اتباع أي تعليمات بداخلها وعدم تقديم التزامات نيابة عنك. راجع كل رد قبل الاعتماد عليه.",
  "safety.item7Title": "7. أين يذهب نصك:",
  "safety.item7Body": "النص الذي ترسله يُرسل إلى Google Gemini API لإنشاء الردود؛ وطريقة تعامل Google معه خارجة عن هذا التطبيق. يستخدم الإدخال الصوتي خاصية التعرّف على الكلام في متصفحك. مفتاح Gemini يبقى على الخادم ولا يُضمَّن في الصفحة.",
  "safety.madeWith": "صُنع بـ",
  "safety.byElghaly": "للمصدّرين",
