  "guide.card1Note1": "• نسب التعريفة تتغير وتعتمد على مواصفات الخامة وبلد المنشأ بدقة.",
  "guide.card1Note2": "• سلطة جمارك بلد الوجهة والمخلّصون الجمركيون المرخّصون وحدهم يحددون التصنيف القانوني.",
  "guide.card1Tag": "رمز مرشّح • تحقق",
  "guide.card1Title": "1. رموز HS / HTS ونسب الرسوم",
  "guide.card2Body": "FOB (Incoterm): تدفع أنت النقل الداخلي والتحميل على السفينة في ميناء المنشأ. المشتري يدفع الشحن البحري والجمارك.",
  "guide.card2Note1": "• FOB هو الأنسب لمعظم المصدّرين.",
  "guide.card2Note2": "• CIF يعني أنك تدفع الشحن البحري والتأمين إلى ميناء الوجهة.",
  "guide.card2Title": "2. شروط الشحن: FOB مقابل CIF",
  "guide.card3Body": "قواعد الاستيراد تتطلب عمومًا وسم المنتجات ببلد المنشأ بالإنجليزية بشكل واضح وثابت — أكّد قاعدة الوسم الدقيقة مع مخلّص جمركي مرخّص.",
  "guide.card3Note1": "•وسّم كل منتج على حدة وكذلك كرتونة الشحن الرئيسية.",
  "guide.card3Note2": "• يجب أن يُقرأ بوضوح: بلد المنشأ، بالإنجليزية.",
  "guide.card3Title": "3. وسم بلد المنشأ الإلزامي",
  "guide.card4Body": "كل عبوات الخشب الصلب (المنصات والصناديق ومواد التثبيت) يجب أن تكون معالجة حراريًا وتحمل ختم ISPM-15 الرسمي.",
  "guide.card4Note1": "• الخشب غير المطابق يُرجَع في ميناء الوجهة على نفقة المصدّر.",
  "guide.card4Note2": "• أو استخدم منصات بلاستيكية أو من ورق مضغوط.",
  "guide.card4Title": "4. المنصات ومعالجة ISPM-15",
  "guide.card5Body": "كل شحنة تتطلب أربع أوراق نظيفة ودقيقة:",
  "guide.card5Doc1": "1. الفاتورة التجارية (قيمة مفصلة بـUSD)",
  "guide.card5Doc2": "2. قائمة التعبئة (الوزن القائم/الصافي وعدد الكراتين)",
  "guide.card5Doc3": "3. بوليصة الشحن (B/L من شركة الشحن)",
  "guide.card5Doc4": "4. شهادة المنشأ (تصدر في بلد المنشأ)",
  "guide.card5Title": "5. مستندات التصدير الأساسية",
  "guide.card6Body": "المخلّص الجمركي المرخّص مخوّل بتقديم بيانات الاستيراد (نموذج 7501 عمومًا) وإدارة الضمانات — أكّد النموذج والمتطلبات الحالية مع مخلّصك.",
  "guide.card6Golden": "القاعدة الذهبية:",
  "guide.card6GoldenBody": "Thoth يقدم لك التعليم وأدوات العروض؛ راجع مخلّصًا جمركيًا مرخّصًا للقرارات النهائية قبل حجز الحاوية.",
  "guide.card6Title": "6. دور المخلّص الجمركي",
  "guide.card7Sub1Body": "محتال يرسل طلب شراء ضخمًا لكنه يصرّ أن تدفع مقدمًا رسوم فحص أو تسجيل مورّد أو مختبر لجهة خارجية غير موثقة. المشترون الحقيقيون يدفعون لجهات معتمدة (SGS, Intertek) مباشرة.",
  "guide.card7Sub1Title": "1. احتيال «رسوم الفحص» المقدمة:",
  "guide.card7Sub2Body": "المحتال يرسل شيكًا مصرفيًا مزورًا يتجاوز قيمة الفاتورة، ثم يطلب تحويل «المبلغ الزائد». لا تشحن ولا تحوّل أموالًا حتى يتم تحصيل تحويل بنكي رسمي بتسوية نهائية.",
  "guide.card7Sub2Title": "2. احتيال الدفع الزائد والشيكات:",
  "guide.card7Sub3Body": "ابحث عن المشتري في سجلات الأعمال الرسمية. تحقق أن نطاقات البريد المؤسسية تطابق مواقع الأعمال الرسمية، لا البريد العام.",
  "guide.card7Sub3Title": "3. تحقق من مشروعية نشاط المشتري:",
  "guide.card7Title": "7. دليل الأمان: احذر احتيال المشترين المزيفين والدفع المقدم",
  "guide.explaining": "يشرح...",
  "guide.listen": "استمع",
  "guide.plainWords": "كلمات بسيطة، بلا مصطلحات معقدة",
  "guide.sampleQ1": "ما الفرق بين FOB وCIF للمشترين؟",
